<?php require_once __DIR__.'/../config/config.php';admin_required();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$name=trim($_POST['name']);$desc=trim($_POST['description']);$cat=$_POST['category']==='Women'?'Women':'Men';$price=(float)$_POST['price'];$sale=(float)$_POST['sale_price'];$stock=max(0,(int)$_POST['stock']);$img=trim($_POST['image_url']);if($id){$s=$pdo->prepare('UPDATE products SET name=?,description=?,category=?,price=?,sale_price=?,stock=?,image_url=?,featured=? WHERE id=?');$s->execute([$name,$desc,$cat,$price,$sale,$stock,$img,(int)isset($_POST['featured']),$id]);}else{$s=$pdo->prepare('INSERT INTO products(name,description,category,price,sale_price,stock,image_url,featured) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$name,$desc,$cat,$price,$sale,$stock,$img,(int)isset($_POST['featured'])]);}$msg='Product saved.';}if(isset($_GET['delete'])){$s=$pdo->prepare('UPDATE products SET active=0 WHERE id=?');$s->execute([(int)$_GET['delete']]);}$products=$pdo->query('SELECT * FROM products ORDER BY created_at DESC')->fetchAll();require 'layout.php';?><h1>Products</h1><div class="admin-card my-3"><h5>Add Product</h5><form method="post" class="row g-2"><?=csrf_field()?><div class="col-md-4"><input class="form-control" name="name" placeholder="Product name" required></div><div class="col-md-2"><select class="form-select" name="category"><option>Men</option><option>Women</option></select></div><div class="col-md-2"><input class="form-control" name="price" type="number" step=".01" placeholder="Regular price" required></div><div class="col-md-2"><input class="form-control" name="sale_price" type="number" step=".01" placeholder="Sale price"></div><div class="col-md-2"><input class="form-control" name="stock" type="number" placeholder="Stock" required></div><div class="col-12"><input class="form-control" name="image_url" placeholder="Image URL (or uploaded image path)"></div><div class="col-12"><textarea class="form-control" name="description" placeholder="Description"></textarea></div><div class="col-12"><label><input type="checkbox" name="featured"> Featured</label> <button class="btn btn-gold float-end">Save Product</button></div></form></div><p><?=e($msg)?></p><div class="table-responsive"><table class="table"><tr><th>Name</th><th>Category</th><th>Price</th><th>Stock</th><th>Active</th><th></th></tr><?php foreach($products as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['category'])?></td><td><?=money($p['price'])?></td><td><?=$p['stock']?></td><td><?=$p['active']?'Yes':'No'?></td><td><a href="?delete=<?=$p['id']?>" onclick="return confirm('Deactivate product?')">Deactivate</a></td></tr><?php endforeach;?></table></div><?php require 'end.php';?>